    "liveApplication": {
      "scenarios": [
        {
          "setup": "You notice attention has been lost in a worry for a minute.",
          "action": "You acknowledge the noticing as a win, then escort attention gently back to the breath.",
          "why": "Valuing the noticing reinforces awareness, and the gentle return trains calm rather than aversion."
        },
        {
          "setup": "You feel frustrated at wandering repeatedly.",
          "action": "You reframe each return as a rep and soften the tone of returning.",
          "why": "Reframing wandering as training converts frustration into persistence and kindness."
        }
      ],
      "perspectives": [
        {
          "role": "Using it",
          "detail": "The return loop builds a self-correcting attention that notices distraction in daily life and comes back to what matters."
        },
        {
          "role": "Facing it",
          "detail": "A practitioner trained in returning recovers focus quickly after interruption instead of staying hijacked."
        }
      ],
      "adaptation": {
        "cues": [
          "Wandering into thought or emotion",
          "Harsh or frustrated returning",
          "Long lost periods without noticing"
        ],
        "adjustments": [
          {
            "if": "Returning feels harsh",
            "then": "Soften the tone; escort attention kindly."
          },
          {
            "if": "Long lost periods",
            "then": "Shorten sits or strengthen the anchor until noticing arises sooner."
          }
        ],
        "learning": "After each sit, note the tone of your returns and whether you valued noticing as success."
      }
    },
    "practiceEngine": {
      "type": "rep-counter",
      "label": "Gentle Returns",
      "targetReps": 10
    }
